import json
import web_search

def weather_script():
    try:
        # Search for weather data from wttr.in
        response = web_search(
            "https://wttr.in/San_Francisco?format=j1",
            num_results=1
        )

        if response["status"] != "success":
            raise ValueError("Failed to fetch weather data")

        # Extract weather data from JSON response
        weather_data = response["results"][0]["data"]

        if not weather_data:
            raise ValueError("No weather data found")

        # Get current weather icon
        icon_url = fetch_url(weather_data["icon"])

        # Print weather information
        print("Current Weather in San Francisco:")
        print(f"Temperature: {weather_data['temp']}°F")
        print(f"Feels like: {weather_data['feels']}°F")
        print(f"Humidity: {weather_data['humidity']}%")
        print(f"Wind speed: {weather_data['wind speed']} mph")

        if icon_url:
            print("\nCurrent weather icon:")
            print(f"✓ {icon_url}")

        return {"status": "success", "weather": weather_data}

    except Exception as e:
        print(f"An error occurred: {e}")
        return {"status": "error", "error": str(e)}

